#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int height, num;
    cin >> height >> num;
    num -= 1;
    string bin_str;
    {
        int temp = num;
        bin_str.clear();
        do {
            bin_str = (char)('0' + (temp & 1)) + bin_str;
            temp >>= 1;
        } while (temp > 0);
    }
    bin_str = string(max(0, height - (int)bin_str.size()), '0') + bin_str;

    string output_str;
    for (int index = 0; index < height; ++index) {
        if (index != 0 && bin_str[index - 1] == '0') {
            output_str += (bin_str[index] == '0') ? '1' : '0';
        } else {
            output_str += bin_str[index];
        }
    }

    long long total_count = 0;
    for (int index = 0; index < height; ++index) {
        total_count += 1;
        if (output_str[index] == '1') {
            total_count += (1LL << (height - index)) - 1;
        }
    }
    cout << total_count << "\n";
    return 0;
}
